// Monthly performance: portfolio value (coins + skins) per student at the end of each month.
// Past months are stored snapshots (demo history generated by the seed); the current month is always live.
import { getWallet } from './trading.js';

const MONTHS_BACK = 5;
export const monthKey = (d) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;
const monthsAgo = (k) => { const n = new Date(); return monthKey(new Date(n.getFullYear(), n.getMonth() - k, 1)); };
const gauss = () => { let u = 0; while (!u) u = Math.random(); return Math.sqrt(-2 * Math.log(u)) * Math.cos(2 * Math.PI * Math.random()); };
const studentsOf = (db) => db.prepare("SELECT student_id, username FROM students WHERE role = 'student' ORDER BY student_id").all();

/** Random-walk the past months backwards from each student's anchor value. anchors = { studentId: coins }. */
export function buildMonthlyHistory(db, anchors) {
  db.exec('DELETE FROM portfolio_snapshots');
  const add = db.prepare('INSERT INTO portfolio_snapshots (student_id, month, portfolio_value) VALUES (?,?,?)');
  for (const [id, anchor] of Object.entries(anchors)) {
    // Each student gets their own "personality": a trend and how bumpy their months are.
    const drift = (Math.random() - 0.5) * 0.16, vol = 0.12 + Math.random() * 0.12;
    let v = anchor;
    for (let k = 1; k <= MONTHS_BACK; k++) {
      let f = 1 + drift + vol * gauss();
      if (Math.random() < 0.3) f += (Math.random() < 0.5 ? -1 : 1) * (0.15 + Math.random() * 0.2); // a big good or bad month
      v = Math.max(100, Math.round(v * Math.min(1.7, Math.max(0.5, f))));
      add.run(Number(id), monthsAgo(k), v);
    }
  }
}

/** For databases created before this feature existed: fill in the past months once. */
export function ensureMonthlyHistory(db) {
  if (db.prepare('SELECT COUNT(*) c FROM portfolio_snapshots').get().c) return;
  const anchors = {};
  for (const s of studentsOf(db)) anchors[s.student_id] = getWallet(db, s.student_id).portfolioValue;
  buildMonthlyHistory(db, anchors);
}

export function monthlyPerformance(db) {
  const students = studentsOf(db);
  const snaps = db.prepare('SELECT student_id, month, portfolio_value FROM portfolio_snapshots').all();
  const keys = [];
  for (let k = MONTHS_BACK; k >= 0; k--) keys.push(monthsAgo(k));
  const rows = keys.map((month, i) => {
    const row = { month };
    for (const s of students) {
      const v = i === keys.length - 1 ? getWallet(db, s.student_id).portfolioValue
        : snaps.find((x) => x.student_id === s.student_id && x.month === month)?.portfolio_value;
      if (v !== undefined) row[s.username] = Math.round(v);
    }
    return row;
  });
  return { students: students.map((s) => s.username), rows };
}
